import java.io.*;
import java.util.*;

public class VanyaAndScaleVariant4 {
    static long[] a;
    static boolean answer;
    static int length;
    static long sumLeft, sumRight;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long w = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        long limit = (long) 1e11;
        a = new long[40];
        int idx = 1;
        long power = 1;
        a[0] = 1;
        if (w <= 3) {
            System.out.println("YES");
            return;
        }
        for (int i = 1; i < 16; i++) {
            a[idx] = power * w;
            power *= w;
            if (power > limit) break;
            idx++;
        }
        sumLeft = 0;
        sumRight = m;
        length = idx;
        answer = false;
        recurse(0);
        System.out.println(answer ? "YES" : "NO");
    }

    static void recurse(int pos) {
        if (pos == length) {
            if (sumLeft == sumRight) {
                answer = true;
            }
            return;
        }
        if (answer) return;
        for (int option = 0; option < 3; option++) {
            if (answer) return;
            if (option == 1) {
                sumLeft += a[pos];
                recurse(pos + 1);
                sumLeft -= a[pos];
            } else if (option == 2) {
                sumRight += a[pos];
                recurse(pos + 1);
                sumRight -= a[pos];
            } else {
                recurse(pos + 1);
            }
        }
    }
}
